co2_orn_to_pn.yaml:
# CO2 pathway, one synapse: the CO2-sensing ORNs (ORN_V) excite the V glomerulus projection neurons (V_ilPN,
# V_l2PN; Suh et al. 2004). Activation only: the sim has no CO2 avoidance behavior. Validation: co2_orn_to_pn.
name: co2_orn_to_pn
seed: 1000
flies: 5
warmup_s: 2
duration_s: 4
stimuli:
  - {at_s: 2.0, for_s: 2.0, target: co2_orn, mode: drive, amp: 0.5}
recordings:
  - {name: co2_pn, neurons: co2_pn}
  - {name: co2_orn, neurons: co2_orn}
  - {name: sensory_all, neurons: "superclass:cb_sensory"}

courtship_song.yaml:
# Courtship song: the male-specific command neuron pIP10, then P1, onto the ps1 wing motor neurons
# (von Philipsborn et al. 2011). Validation: courtship_song (pIP10, PASS) and p1_courtship_song (P1, too weak).
name: courtship_song
seed: 1000
flies: 5
warmup_s: 2
duration_s: 6
stimuli:
  - {at_s: 1.5, for_s: 1.5, target: pip10, mode: drive, amp: 0.5}
  - {at_s: 4.0, for_s: 1.5, target: p1, mode: drive, amp: 0.5}
recordings:
  - {name: ps1_motor, neurons: ps1}
  - {name: song_wm, neurons: song_wm}
  - {name: pip10, neurons: pip10}

cva_pheromone.yaml:
# cVA pathway, as activation: drive the DA1 olfactory receptor neurons (the Or67d cVA sensors), then the DA1
# projection neurons, and record both and their lateral horn / aSP targets (LHAV4a4, LHAV4c1, LH008m).
# Validation: or67d_to_da1pn and da1pn_to_lh_asp.
name: cva_pheromone
seed: 1000
flies: 5
warmup_s: 2
duration_s: 6
stimuli:
  - {at_s: 1.5, for_s: 1.5, target: or67d_orn, mode: drive, amp: 0.5}
  - {at_s: 4.0, for_s: 1.5, target: da1_pn, mode: drive, amp: 0.5}
recordings:
  - {name: da1_pn, neurons: da1_pn}
  - {name: da1_lh_asp, neurons: da1_lh_asp}
  - {name: or67d_orn, neurons: or67d_orn}

decoy_courtship.yaml:
# The decoy female's input, as activation: drive the foreleg GRNs annotated putative ppk23/ppk25 (LgLG5-8) and record
# the ascending vAB3/PPN1 neurons, P1 and the ps1 song motor neurons. Validation: foreleg_grn_to_p1 (too weak: FAIL).
name: decoy_courtship
seed: 1000
flies: 5
warmup_s: 2
duration_s: 6
stimuli:
  - {at_s: 1.5, for_s: 2.0, target: foreleg_pheromone_grn, mode: drive, amp: 0.6}
recordings:
  - {name: foreleg_grn, neurons: foreleg_pheromone_grn}
  - {name: vab3_ppn1, neurons: vab3_ppn1}
  - {name: p1, neurons: p1}
  - {name: ps1, neurons: ps1}

grooming_hierarchy.yaml:
# Grooming hierarchy (Seeds et al. 2014): the abdomen's mechanosensory neurons alone, then head bristles and abdomen
# together. Anterior-first priority would show as front-leg motor neurons winning and the hind-leg response shrinking
# when the head is added. It doesn't in this sim (validation: grooming_hierarchy, FAIL).
name: grooming_hierarchy
seed: 1000
flies: 5
warmup_s: 2
duration_s: 6
stimuli:
  - {at_s: 1.0, for_s: 1.5, target: groom_posterior, mode: drive, amp: 0.5}
  - {at_s: 4.0, for_s: 1.5, target: groom_posterior, mode: drive, amp: 0.5}
  - {at_s: 4.0, for_s: 1.5, target: groom_anterior, mode: drive, amp: 0.5}
recordings:
  - {name: mn_front, neurons: mn_front}
  - {name: mn_hind, neurons: mn_hind}

light_clock_dfb.yaml:
# Daylight onto the clock: photoreceptors plus the morning clock neurons l-LNv/s-LNv, the way the day/night cycle
# drives them outdoors (the direct LNv drive is a game rule), recording the clock neurons and the dorsal fan-shaped
# body (FB6/FB7) that the SLEEP readout watches. Not a circadian rhythm: the sim has no molecular clock.
name: light_clock_dfb
seed: 1000
flies: 5
warmup_s: 2
duration_s: 4
stimuli:
  - {at_s: 2.0, for_s: 2.0, target: light, strength: 1.0}
  - {at_s: 2.0, for_s: 2.0, target: clock, strength: 1.0}
recordings:
  - {name: clock_l_lnv, neurons: "type:l-LNv"}
  - {name: clock_s_lnv, neurons: "type:s-LNv"}
  - {name: dfb_sleep_fb6, neurons: "prefix:FB6"}
  - {name: dfb_sleep_fb7, neurons: "prefix:FB7"}

looming-giant-fiber.yaml:
# Looming detectors LPLC2/LC4 driven like a looming object and the giant fiber DNp01 recorded. The surgery silences
# the looming detectors themselves, so the same stimulus should no longer reach DNp01.
# Each seed also runs unperturbed as its control.
name: looming-giant-fiber
seed: 100
flies: 5
warmup_s: 2
duration_s: 3
surgery: {"type:LPLC2,LC4": -1}
stimuli:
  - {at_s: 1.0, for_s: 1.0, target: loom, strength: 0.9, recruit: 0.6}
recordings:
  - {name: giant_fiber, neurons: dnp01}
  - {name: looming_detectors, neurons: loom}
  - {name: descending, neurons: "superclass:descending_neuron"}

male_aggression.yaml:
# Male aggression neurons: P1 (the pC1 types annotated "Cachero 2010: pMP-e; Yu 2010: pMP4"; Hoopfer et al. 2015)
# together with the tachykinin/fru neurons AVLP727m ("Asahina 2014: TK-FruM"), recording the pC1 cluster the game's
# LUNGE reads, the song motor neurons and the descending neurons. The lunge itself is a game rule.
name: male_aggression
seed: 1000
flies: 5
warmup_s: 2
duration_s: 4
stimuli:
  - {at_s: 2.0, for_s: 2.0, target: p1, mode: drive, amp: 0.5}
  - {at_s: 2.0, for_s: 2.0, target: "type:AVLP727m", mode: drive, amp: 0.5}
recordings:
  - {name: pc1_cluster, neurons: "prefix:pC1"}
  - {name: tk_frum, neurons: "type:AVLP727m"}
  - {name: ps1_song_motor, neurons: ps1}
  - {name: descending, neurons: "superclass:descending_neuron"}

mic_hum_pulses.yaml:
# 3.0 day 3, Microphone -> Johnston's organ: a stimulus protocol with a SYNTHETIC 200 Hz hum in 35 ms pulses (never the microphone) from 1 s to 4 s.
# JO-A/B are driven through core/mic.py's analysis (GAME RULE); the P1 cluster and the song motor neurons are recorded.
name: mic-hum-pulses
seed: 1000
flies: 2
warmup_s: 1
duration_s: 6
audio: {hz: 200, ipi_ms: 35, amp: 0.1, at_s: 1, seconds: 3}
recordings:
  - {name: JO-A, neurons: "prefix:JO-A"}
  - {name: JO-B, neurons: "prefix:JO-B"}
  - {name: P1 cluster, neurons: "p1"}
  - {name: song motor neurons, neurons: "ps1"}

plume_tracking.yaml:
# Olfactory and wind input, as activation: drive the olfactory receptor neurons, then the JO-C/E wind neurons, and
# record the right steering neurons. Not plume tracking: that is assays.plume_tracking_fly, whose navigation is a game
# rule computed from the geometry (the open field has no plume).
name: plume_tracking
seed: 1000
flies: 5
warmup_s: 2
duration_s: 6
stimuli:
  - {at_s: 1.0, for_s: 1.0, target: orn, mode: drive, amp: 0.5}
  - {at_s: 3.0, for_s: 1.0, target: wind, mode: drive, amp: 0.4}
recordings:
  - {name: orn, neurons: orn}
  - {name: wind, neurons: wind}
  - {name: dna_steer_r, neurons: dna_steer_r}

replay_check.yaml:
# What CI's replay determinism job records and replays (checks.yml): pokes (which draw from the brain's own random
# generator), a held drive and brain surgery, so every kind of input a .ktfreplay stores is exercised.
name: replay_check
seed: 1003
warmup_s: 0.2
duration_s: 1.5
surgery: {dnp01: -1}
stimuli:
  - {at_s: 0.1, for_s: 0.4, target: loom, mode: poke, strength: 0.7}
  - {at_s: 0.3, for_s: 0.5, target: sweet, mode: drive, amp: 0.5}
  - {at_s: 0.9, for_s: 0.3, target: "prefix:JO-", mode: poke, strength: 0.9}
recordings:
  - {name: mn9, neurons: mn9}

thermogenetic_dnp01.yaml:
# 3.0 day 2, Thermogenetics: TrpA1 in DNp01 (chosen by driver line), room warmed from 22 C to 32 C at t = 2 s.
# GAME RULE: TrpA1 turns on from 25 C and is fully on at 29 C (onset after Pulver et al. 2009); the current size and kinetics are
# game rules (lab/thermogenetics.py). Each seed also runs without the channel (no expression) through a second protocol file;
# here the giant fiber is recorded before and after the shift.
name: thermogenetic-dnp01
seed: 100
flies: 5
warmup_s: 2
duration_s: 5
thermogenetics:
  expression:
    - {effector: trpa1, target: "line:SS00727"}
  temperature_c:
    - {at_s: 0, c: 22}
    - {at_s: 2, c: 32}
  kinetics: real
recordings:
  - {name: giant_fiber, neurons: dnp01}
  - {name: descending, neurons: "superclass:descending_neuron"}

thermosensory_pathways.yaml:
# Hot and cold antennal neurons onto their projection neurons (Gallio et al. 2011): TRN_VP2 -> VP2 PNs, then
# TRN_VP3a/b -> VP3 PNs. One-synapse activation, not thermotaxis. Validation: hot_trn_to_vp2pn, cold_trn_to_vp3pn.
name: thermosensory_pathways
seed: 1000
flies: 5
warmup_s: 2
duration_s: 5
stimuli:
  - {at_s: 1.5, for_s: 1.5, target: trn_vp2, mode: drive, amp: 0.5}
  - {at_s: 3.5, for_s: 1.5, target: trn_vp3, mode: drive, amp: 0.5}
recordings:
  - {name: vp2_pn_hot, neurons: vp2_pn}
  - {name: vp3_pn_cold, neurons: vp3_pn}
  - {name: hot_sensors, neurons: trn_vp2}
  - {name: cold_sensors, neurons: trn_vp3}

weather_storm.yaml:
# 3.0 day 3, Rain and storms: a stimulus protocol. Rain on the touch neurons by body part, gusts on the wind neurons JO-C/E, lightning on
# the photoreceptors (game/weather.py; game rules on the connectome's own neurons). Compare with the same protocol without `weather:`.
name: weather-storm
seed: 1000
flies: 2
warmup_s: 1
duration_s: 12
weather: {rain: 0.8, gust_hz: 0.3, storm: true, wind_speed: 2}
recordings:
  - {name: wing touch, neurons: "wing"}
  - {name: body touch, neurons: "body"}
  - {name: humidity, neurons: "humid"}
  - {name: wind JO-C/E, neurons: "wind"}
  - {name: photoreceptors, neurons: "light"}
